\title{The Area Function of the Berggren Tree\\ and the Congruent Number Problem}
\author{Aristotle}
\date{15 September 2026}

\begin{document}
\maketitle

\begin{abstract}
The Berggren--Barning--Hall tree enumerates the primitive Pythagorean triples exactly once
each, as a ternary tree rooted at $(3,4,5)$. We study the \emph{area function} of this tree,
which in Euclid coordinates $(m,n)\mapsto(m^2-n^2,2mn,m^2+n^2)$ is the quartic form
$\Ar(m,n)=mn(m^2-n^2)=mn(m-n)(m+n)$. Our main theorem is that the squarefree parts of the
values of $\Ar$ on admissible seeds are exactly the congruent numbers: a squarefree positive
integer $s$ is the area of some rational right triangle if and only if some node of the tree
has area $sk^2$ for an integer $k>0$. Combined with an explicit correspondence with the
congruent number curve $E_s:y^2=x^3-s^2x$, this yields a three-way equivalence between
rational right triangles of area $s$, nodes of the tree of area $s$ times a square, and
rational points of $E_s$ with $x>0$, $y\ne 0$. The tree formulation supports its own infinite
descent, in which ``smaller'' means ``closer to the root''. We use it to prove
unconditionally that no node has square area (Fermat's right triangle theorem; $1$ is not
congruent), that no node has area twice a square ($2$ is not congruent), and that for every
prime $p\equiv 3\pmod 8$ no node has area $pk^2$ (Genocchi's theorem), giving an infinite
family of non-congruent numbers. We then develop the first structure theory of the area
function: exact increment identities along the three branches, a $6\times$ growth law along
the middle branch, the silver law $\Ar_d=2t_d^2+(-1)^{d+1}t_d$ along the Pell spine, the
bound $\Ar_d\ge 6^{d+1}$, and properness ($\Ar(m,n)>m^2$). Properness makes the tree a
computable model in which density questions about congruent numbers --- equivalent in depth
to rank distribution for $E_s$ --- become finitary statements about the recurrence of square
classes among the values of a single quartic form.
\end{abstract}

\noindent\textbf{Keywords:} congruent numbers, Pythagorean triples, Berggren tree, infinite
descent, elliptic curves, Pell numbers, silver ratio, Genocchi's theorem.

\section{Introduction}

A positive rational number $N$ is a \emph{congruent number} if it is the area of a right
triangle whose three sides are positive rationals. Deciding which integers are congruent is
a problem of great antiquity; it appears in Arab manuscripts of the tenth century and in
Fibonacci's \emph{Liber Quadratorum} (1225), and Bachet's 1621 edition of Diophantus
popularised it in Europe. Fermat proved that $1$ is not congruent by infinite descent;
Genocchi (1855) proved that no prime $p\equiv 3\pmod 8$ is congruent. In modern language,
$N$ is congruent if and only if the elliptic curve $y^2=x^3-N^2x$ has positive rank, which
places the problem inside the Birch--Swinnerton-Dyer circle of ideas: Tunnell's theorem
(1983) provides a finite criterion whose sufficiency remains conditional.

This paper studies the \emph{triangle} side of the problem through a combinatorial object in
which that side is completely explicit. Barning (1963) and Hall (1970) showed that three
fixed unimodular matrices, applied repeatedly to $(3,4,5)$, generate every primitive
Pythagorean triple exactly once; equivalently, in Euclid coordinates, every admissible seed
is reached from $(2,1)$ by a unique word in three affine moves. We attach to each node of
this tree its area, and prove that the resulting function is a faithful model of the
congruent number problem.

\section{Definitions}

\begin{definition}[Congruent number]
A rational number $N$ is \emph{congruent} if there exist $a,b,c\in\Q_{>0}$ with
$a^2+b^2=c^2$ and $ab=2N$.
\end{definition}

\begin{definition}[Primitive Pythagorean triple]
A triple $(a,b,c)$ of positive integers is a \emph{primitive Pythagorean triple} (PPT) if
$a^2+b^2=c^2$ and $\gcd(a,b)=1$.
\end{definition}

\begin{definition}[Admissible seed; Euclid map]
A pair $(m,n)\in\Z^2$ is an \emph{admissible seed} if $m>n>0$, $\gcd(m,n)=1$ and $m-n$ is
odd. The \emph{Euclid map} is $\EE(m,n)=(m^2-n^2,\,2mn,\,m^2+n^2)$.
\end{definition}

\begin{proposition}[Euclid's classification]
$\EE$ is a bijection from admissible seeds onto the PPTs with even second entry; every PPT
is of this form or is the leg-swap of one.
\end{proposition}

\begin{definition}[Berggren moves and the tree]
On admissible seeds define
\[
A(m,n)=(2m-n,\,m),\qquad B(m,n)=(2m+n,\,m),\qquad C(m,n)=(m+2n,\,n).
\]
The \emph{Berggren tree} is the rooted ternary tree with root $(2,1)$ whose children are
$A(v),B(v),C(v)$.
\end{definition}

\begin{theorem}[Barning--Hall; used as input]
Every admissible seed is obtained from $(2,1)$ by a unique finite word in $\{A,B,C\}$;
consequently the nodes, together with their leg-swaps, enumerate all PPTs exactly once.
\end{theorem}

\begin{definition}[Area function]
For $m,n\in\Z$ set $\Ar(m,n)=mn(m^2-n^2)=mn(m-n)(m+n)$, and for an integer triple
$v=(a,b,c)$ set $\mathrm{area}(v)=\tfrac12 ab$.
\end{definition}

\begin{proposition}
$\mathrm{area}(\EE(m,n))=\Ar(m,n)$, and $\Ar(m,n)>0$ whenever $m>n>0$.
\end{proposition}

\begin{definition}[Congruent number curve]
For $N\in\Q$ put $E_N:\;y^2=x^3-N^2x$.
\end{definition}

\section{Elementary properties of the area function}

\begin{theorem}[Divisibility by six]
For all integers $m,n$ we have $6\mid \Ar(m,n)$.
\end{theorem}

\begin{proof}[Proof sketch]
The claim depends only on $m,n$ modulo $6$, and the $36$ cases are checked directly.
Conceptually: one of $m$, $n$, $m-n$ is even, and one of $m$, $n$, $m-n$, $m+n$ is divisible
by $3$, since $3\nmid mn$ forces $m\equiv\pm n\pmod 3$.
\end{proof}

\begin{theorem}[Scaling]
If $N$ is congruent and $t\in\Q_{>0}$, then $Nt^2$ is congruent.
\end{theorem}

\begin{proof}
Scale the sides of a witnessing triangle by $t$: the Pythagorean relation is homogeneous of
degree $2$, and the area is multiplied by $t^2$.
\end{proof}

\begin{theorem}[Square-class invariance]\label{thm:sqclass}
For $N\in\Q$ and $t\in\Q^{\times}$, $N$ is congruent if and only if $Nt^2$ is congruent.
\end{theorem}

\begin{proof}
Apply the previous theorem with $|t|$ in one direction, and with $|t|^{-1}$ applied to
$Nt^2$ in the other, using $|t|^2=t^2$.
\end{proof}

\begin{corollary}
For every admissible seed $(m,n)$, the integer $\Ar(m,n)$ is a congruent number, and so is
its squarefree part.
\end{corollary}

\section{The main equivalence}

\subsection{Descent from a rational triangle to a primitive triple}

\begin{lemma}[Squarefree cancellation]\label{lem:cancel}
Let $s$ be squarefree, $g\ne 0$, and $Ag^2=sd^2$ with $A,d\in\Z$. Then $A=sk^2$ for some
$k\in\Z$.
\end{lemma}

\begin{proof}[Proof sketch]
Writing $e=\gcd(g,d)$, $g=eg_1$, $d=ed_1$ and cancelling $e^2$ reduces to $\gcd(g,d)=1$.
Then $g^2\mid sd^2$ with $\gcd(g^2,d^2)=1$ gives $g^2\mid s$, so $g=\pm1$ by squarefreeness,
whence $A=sd^2$.
\end{proof}

\begin{theorem}[Descent to a primitive triple]\label{thm:descent}
Let $s$ be a squarefree positive congruent number. Then there are positive integers
$x,y,z,k$ with $x^2+y^2=z^2$, $\gcd(x,y)=1$ and $xy=2sk^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Clearing a common denominator $D$ of a rational witness gives integers with $x^2+y^2=z^2$
and $xy=2sD^2$. Let $g=\gcd(x,y)$; then $g^2\mid z^2$, so $g\mid z$ and
$(x/g,y/g,z/g)$ is primitive with leg product $P$ satisfying $Pg^2=2sD^2$. Halving (the leg
product of a Pythagorean triple is even) and applying Lemma~\ref{lem:cancel} gives
$P=2sk^2$.
\end{proof}

\subsection{The tree form}

\begin{theorem}[Areas of seeds are the congruent numbers]\label{thm:main1}
Let $s$ be squarefree. Then $s$ is a congruent number if and only if there are an admissible
seed $(m,n)$ and an integer $k>0$ with $\Ar(m,n)=sk^2$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) $sk^2$ is the area of an integral right triangle, hence congruent; apply
Theorem~\ref{thm:sqclass}. ($\Rightarrow$) By Theorem~\ref{thm:descent} there is a primitive
triple with $xy=2sk^2$; by Euclid's classification $(x,y,z)$ or $(y,x,z)$ equals
$\EE(m,n)$, and then $xy=(m^2-n^2)(2mn)=2\Ar(m,n)$.
\end{proof}

\begin{theorem}[Tree form]
Let $s$ be squarefree. Then $s$ is a congruent number if and only if some node of the
Berggren tree, or of its leg-swapped copy, has area $sk^2$ for an integer $k>0$.
\end{theorem}

\begin{corollary}[Squarefree parts]
Every node area $\Ar(m,n)$ factors uniquely as $sk^2$ with $s$ squarefree and $k>0$, and
this $s$ is a congruent number. The map sending a node to the squarefree part of its area is
a surjection onto the set of congruent numbers.
\end{corollary}

\subsection{The elliptic curve side}

\begin{theorem}[Triangle to point]
If $N$ is congruent with witness $(a,b,c)$, then $\bigl(\tfrac{a(a+c)}2,\tfrac{a^2(a+c)}2\bigr)$
lies on $E_N$ with $x>0$ and $y>0$.
\end{theorem}

\begin{proof}[Proof sketch]
Substituting $N=ab/2$ and $c^2=a^2+b^2$ turns $x^3-N^2x-y^2$ into a polynomial identity
modulo $c^2-a^2-b^2$. Positivity is clear.
\end{proof}

\begin{theorem}[Point to triangle]
Let $N>0$ and let $(x,y)\in\Q^2$ lie on $E_N$ with $x>0$, $y\ne 0$. Then $x>N$ and, after
replacing $y$ by $|y|$,
\[
\left(\frac{x^2-N^2}{y},\ \frac{2Nx}{y},\ \frac{x^2+N^2}{y}\right)
\]
is a rational right triangle of area $N$.
\end{theorem}

\begin{proof}[Proof sketch]
From $y^2=x(x-N)(x+N)>0$ and $x>0$ we get $x>N$, so all three entries are positive. The
identity $(x^2-N^2)^2+(2Nx)^2=(x^2+N^2)^2$ is formal, and the area is
$\dfrac{(x^2-N^2)\cdot 2Nx}{2y^2}=\dfrac{N x(x^2-N^2)}{x^3-N^2x}=N$.
\end{proof}

\begin{theorem}[Three-way equivalence]
For a squarefree positive integer $s$ the following are equivalent:
\begin{enumerate}
\item $s$ is a congruent number;
\item some node of the Berggren tree (or its swap) has area $sk^2$ with $k>0$ an integer;
\item $y^2=x^3-s^2x$ has a rational point with $x>0$ and $y\ne 0$.
\end{enumerate}
\end{theorem}

Since the torsion of $E_s(\Q)$ is $(\Z/2)^2$, generated by the points of order two at
$x=0,\pm s$, none of which has $y\ne 0$, condition (3) holds precisely when $E_s$ has
positive rank. The tree data is therefore a faithful encoding of rank positivity.

\section{Unconditional laws by tree-native descent}

\begin{lemma}[Four coprime factors]\label{lem:four}
If $(m,n)$ is admissible, then $m$, $n$, $m-n$, $m+n$ are positive and pairwise coprime, and
$m\pm n$ are odd.
\end{lemma}

\begin{lemma}[Four squares]
If $\Ar(m,n)=k^2$ for an admissible seed, then $m=a^2$, $n=b^2$, $m-n=c^2$, $m+n=d^2$ with
$a,b,c,d>0$ and $c,d$ odd.
\end{lemma}

\begin{theorem}[Fermat's right triangle theorem, tree form]\label{thm:fermat}
For every admissible seed $(m,n)$ and every integer $k$, $\Ar(m,n)\ne k^2$. Consequently $1$
is not a congruent number, and neither is $t^2$ for any $t\in\Q^\times$.
\end{theorem}

\begin{proof}[Proof sketch]
With $m=a^2$, $n=b^2$, $m-n=c^2$, $m+n=d^2$ and $c,d$ odd, set $u=\tfrac{d+c}2$,
$v=\tfrac{d-c}2$. Then $u^2+v^2=m=a^2$ and $2uv=n=b^2$, and $\gcd(u,v)=1$. Hence $(u,v,a)$
is a primitive Pythagorean triple, so it equals $\EE(p,q)$ for an admissible seed $(p,q)$
with $a=p^2+q^2$. Coprimality turns $2uv=b^2$ into ``even leg $=2g^2$, odd leg $=h^2$'', and
substituting yields
\[
\Ar(p,q)=\tfrac12(2pq)(p^2-q^2)=g^2h^2=(gh)^2 .
\]
Since $p<p^2+q^2=a$ and $a^2=m$ with $a\ge2$, we have $p<a<m$: the seed strictly shrinks,
so iteration contradicts well-ordering.
\end{proof}

\begin{theorem}[Twice a square]
For every admissible seed and every integer $k$, $\Ar(m,n)\ne 2k^2$; hence $2$ is not a
congruent number, and neither is $2t^2$ for $t\in\Q^\times$.
\end{theorem}

\begin{proof}[Proof sketch]
The four factors are pairwise coprime, so the lone factor $2$ goes to the even one of $m,n$
and the other three factors are squares. If $m=2a^2$, $n=b^2$, $m-n=c^2$, $m+n=d^2$, then
$c^2+d^2=2m=4a^2$ with $c,d$ odd, impossible modulo $8$. If $n=2b^2$, $m=a^2$, then with
$u=\tfrac{d+c}2$, $v=\tfrac{d-c}2$ one gets $u^2+v^2=a^2$, $uv=b^2$, $\gcd(u,v)=1$, so
$u=g^2$, $v=h^2$ and $g^4+h^4=a^2$, contradicting Fermat's theorem on $x^4+y^4=z^2$.
\end{proof}

\begin{lemma}[Coprime splitting with a prime]
Let $p>0$ be prime and $A,B>0$ coprime with $AB=pk^2$. Then either $A=pa^2,\ B=b^2$ or
$A=a^2,\ B=pb^2$ with $a,b>0$.
\end{lemma}

\begin{lemma}[Four shapes]
Let $p>0$ be prime and $(m,n)$ admissible with $\Ar(m,n)=pk^2$. Then exactly one of the four
pairwise coprime factors is $p$ times a square and the other three are squares:
\begin{align*}
&\text{(S1)}\; m=pa^2,\ n=b^2,\ m-n=c^2,\ m+n=d^2; &
&\text{(S2)}\; m=a^2,\ n=pb^2,\ m-n=c^2,\ m+n=d^2;\\
&\text{(S3)}\; m=a^2,\ n=b^2,\ m-n=pc^2,\ m+n=d^2; &
&\text{(S4)}\; m=a^2,\ n=b^2,\ m-n=c^2,\ m+n=pd^2.
\end{align*}
\end{lemma}

\begin{lemma}[Three shapes die modulo $8$]\label{lem:mod8}
Let $p\equiv 3\pmod 8$ be prime and $(m,n)$ admissible with $\Ar(m,n)=pk^2$. Then (S1), (S3)
and (S4) are impossible, and in (S2) the integer $a$ is odd.
\end{lemma}

\begin{proof}[Proof sketch]
Odd squares are $\equiv1\pmod 8$ and even squares are $\equiv 0$ or $4\pmod 8$; $m\pm n$ are
odd by Lemma~\ref{lem:four}.
In (S1), $2m=c^2+d^2\equiv 2\pmod 8$ with $c,d$ odd, so $m\equiv1\pmod4$ and $m$ is odd,
forcing $a$ odd and $m=pa^2\equiv 3\pmod 8$ --- a contradiction.
In (S3), $m-n=pc^2\equiv 3\pmod 8$ with $c$ odd. If $b$ is even then $m-n\equiv 1$ or
$5\pmod 8$; if $a$ is even then $m+n=d^2\equiv 1\pmod 8$ forces $m\equiv 0\pmod 8$ and hence
$m-n\equiv 7\pmod 8$. Both contradict $m-n \equiv 3$.
In (S4), $m-n\equiv 1$ and $m+n\equiv 3\pmod 8$ give $2m\equiv4$, so $m$ is even and $n$
odd; then $m+n\equiv 1$ or $5\pmod 8$, not $3$.
In (S2), $2m=c^2+d^2\equiv 2 \pmod 8$ makes $m=a^2$ odd, so $a$ is odd.
\end{proof}

\begin{lemma}[The surviving shape descends]
Let $p\equiv 3\pmod 8$ be prime and $(m,n)$ admissible with $\Ar(m,n)=pk^2$. Then there is an
admissible seed $(r,t)$ with $r<m$ and $\Ar(r,t)=p{k'}^2$ for some integer $k'$.
\end{lemma}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:mod8} we are in shape (S2): $m=a^2$ odd, $n=pb^2$ with $b$ even. With
$u=\tfrac{d+c}2$, $v=\tfrac{d-c}2$ we get coprime positive integers with $u^2+v^2=a^2$ and
$2uv=pb^2$, so $(u,v,a)$ is a primitive triple, equal to $\EE(r,t)$ with $a=r^2+t^2$.
Splitting $2uv=pb^2$ into coprime parts gives $\Ar(r,t)=\tfrac12(2rt)(r^2-t^2)=p{k'}^2$, and
$r<a<m$ as in Theorem~\ref{thm:fermat}.
\end{proof}

\begin{theorem}[Genocchi's theorem, tree form]
Let $p\equiv 3\pmod 8$ be prime. Then no node of the Berggren tree has area $pk^2$;
consequently $p$ is not a congruent number, and neither is $pt^2$ for any $t\in\Q^\times$.
In particular $3$, $11$, $19$, $43$, $59$, $67$, $83$, $107$, $131,\dots$ are non-congruent.
\end{theorem}

\section{Structure of the area function}

\subsection{Monotonicity}

\begin{theorem}[Exact increment identities]\label{thm:incr}
For all $m,n\in\Z$,
\begin{align*}
\Ar(2m-n,\,m)&=\Ar(m,n)+6m^2(m-n)^2,\\
\Ar(m+2n,\,n)&=\Ar(m,n)+6n^2(m+n)^2,\\
\Ar(2m+n,\,m)&=6\,\Ar(m,n)+m(m+n)\bigl(6m^2-mn+7n^2\bigr).
\end{align*}
\end{theorem}

\begin{corollary}
Each of the three children of a node has strictly larger area, and along the middle branch
$\Ar(2m+n,m)>6\,\Ar(m,n)$.
\end{corollary}

\subsection{The Pell spine and the silver law}

\begin{definition}
Let $\sigma_0=(2,1)$ and $\sigma_{d+1}=B(\sigma_d)$, i.e.\ $m_{d+1}=2m_d+n_d$,
$n_{d+1}=m_d$; the seeds are $(2,1),(5,2),(12,5),(29,12),(70,29),\dots$, consecutive Pell
numbers.
\end{definition}

\begin{theorem}[Pell/silver identity]
$m_d^2-2m_dn_d-n_d^2=(-1)^{d+1}$ for all $d\ge0$.
\end{theorem}

\begin{proof}
The substitution $(m,n)\mapsto(2m+n,m)$ negates the form, and the base case is $4-4-1=-1$.
\end{proof}

\begin{theorem}[Silver law for spine areas]
With $t_d=m_dn_d$ we have $\Ar(\sigma_d)=2t_d^{\,2}+(-1)^{d+1}t_d$.
\end{theorem}

The first values are $6,\,210,\,7140,\,242556,\,8239770$. Since $m_d/n_d\to 1+\sqrt2$, the
spine areas grow like a constant times $(17+12\sqrt2)^d$; an unconditional bound is
$\Ar(\sigma_d)\ge 6^{d+1}$. Note that $8\Ar(\sigma_d)+1=(4t_d\pm1)^2$ is always a perfect
square: along the spine the quartic collapses to the quadratic $2t^2\pm t$.

\subsection{Properness}

\begin{theorem}
For every admissible seed, $\Ar(m,n)>m^2$. Consequently, for every $X$ the set of admissible
seeds with $\Ar(m,n)\le X$ is finite and contained in $\{1\le n<m\le\sqrt X\}$.
\end{theorem}

\begin{proof}
$\Ar(m,n)=mn(m-n)(m+n)\ge m\cdot1\cdot1\cdot(m+1)>m^2$.
\end{proof}

