"""Algorithm: certified congruent number generation by bounded seed enumeration."""

from __future__ import annotations

from fractions import Fraction
from math import gcd, isqrt
from typing import Dict, List, Tuple

Seed = Tuple[int, int]
Certificate = Tuple[int, Seed, int, Tuple[Fraction, Fraction, Fraction]]


def smallest_prime_factor_sieve(limit: int) -> List[int]:
    """spf[x] is the least prime factor of x, for 2 <= x <= limit."""
    spf = list(range(limit + 1))
    i = 2
    while i * i <= limit:
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    return spf


def is_admissible(m: int, n: int) -> bool:
    """m > n > 0, coprime, of opposite parity."""
    return m > n > 0 and gcd(m, n) == 1 and (m - n) % 2 == 1


def squarefree_part_of_area(m: int, n: int, spf: List[int]) -> int:
    """Squarefree part of A(m,n) = m n (m-n)(m+n), via the four coprime factors."""
    exponents: Dict[int, int] = {}
    for factor in (m, n, m - n, m + n):
        while factor > 1:
            p = spf[factor]
            while factor % p == 0:
                exponents[p] = exponents.get(p, 0) + 1
                factor //= p
    s = 1
    for p, e in exponents.items():
        if e % 2 == 1:
            s *= p
    return s


def certified_congruent_numbers(bound: int) -> Dict[int, Certificate]:
    """All congruent numbers certified by an admissible seed with m <= bound.

    Returns a dictionary s -> (area, seed, k, triangle) where the triangle has
    rational sides and area exactly s.
    """
    spf = smallest_prime_factor_sieve(2 * bound)
    best: Dict[int, Certificate] = {}
    for m in range(2, bound + 1):
        for n in range(1, m):
            if not is_admissible(m, n):
                continue
            area = m * n * (m - n) * (m + n)
            s = squarefree_part_of_area(m, n, spf)
            k = isqrt(area // s)
            assert s * k * k == area
            triangle = (Fraction(m * m - n * n, k), Fraction(2 * m * n, k),
                        Fraction(m * m + n * n, k))
            if s not in best or area < best[s][0]:
                best[s] = (area, (m, n), k, triangle)
    return best


if __name__ == "__main__":
    table = certified_congruent_numbers(60)
    for s in sorted(t for t in table if t <= 100):
        area, seed, k, (a, b, c) = table[s]
        assert a * a + b * b == c * c and a * b == 2 * s
        print(f"s = {s:>4}   seed {seed}   area {area} = {s} * {k}^2   "
              f"triangle ({a}, {b}, {c})")

"""Algorithm: unique address of a node by inverse Berggren descent."""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Tuple

Seed = Tuple[int, int]

ROOT: Seed = (2, 1)


def is_admissible(m: int, n: int) -> bool:
    return m > n > 0 and gcd(m, n) == 1 and (m - n) % 2 == 1


def apply_word(word: str, seed: Seed = ROOT) -> Seed:
    """Apply a word in the generators A, B, C to a seed."""
    m, n = seed
    for letter in word:
        if letter == "A":
            m, n = 2 * m - n, m
        elif letter == "B":
            m, n = 2 * m + n, m
        elif letter == "C":
            m, n = m + 2 * n, n
        else:
            raise ValueError(f"unknown generator {letter!r}")
    return (m, n)


def parent(seed: Seed) -> Optional[Tuple[str, Seed]]:
    """The generator that produced this seed and the parent seed, or None at the root."""
    m, n = seed
    if (m, n) == ROOT:
        return None
    if m < 2 * n:
        return ("A", (n, 2 * n - m))     # (m,n) = (2p-q, p) with q = 2n - m
    if m < 3 * n:
        return ("B", (n, m - 2 * n))     # (m,n) = (2p+q, p) with q = m - 2n
    return ("C", (m - 2 * n, n))         # (m,n) = (p+2q, q) with p = m - 2n


def address(seed: Seed) -> str:
    """The unique word in {A, B, C} taking the root (2,1) to this seed."""
    if not is_admissible(*seed):
        raise ValueError(f"{seed} is not an admissible Euclid seed")
    letters: List[str] = []
    current = seed
    while True:
        step = parent(current)
        if step is None:
            return "".join(reversed(letters))
        letter, current = step
        letters.append(letter)


def path_to_root(seed: Seed) -> List[Seed]:
    """The chain of ancestors from the given seed up to the root."""
    chain = [seed]
    current = seed
    while True:
        step = parent(current)
        if step is None:
            return chain
        _, current = step
        chain.append(current)


if __name__ == "__main__":
    for seed in [(2, 1), (5, 4), (16, 9), (9, 8), (12, 5), (26, 1)]:
        word = address(seed)
        assert apply_word(word) == seed
        chain = " -> ".join(str(s) for s in reversed(path_to_root(seed)))
        print(f"{str(seed):<10} depth {len(word):>3}  address {word or '(root)'}")
        print(f"           {chain}")

"""Algorithm: explicit bridge between tree nodes and points of y^2 = x^3 - s^2 x."""

from __future__ import annotations

from fractions import Fraction
from math import gcd, isqrt
from typing import Dict, Tuple

Seed = Tuple[int, int]
Triangle = Tuple[Fraction, Fraction, Fraction]
Point = Tuple[Fraction, Fraction]


def is_admissible(m: int, n: int) -> bool:
    return m > n > 0 and gcd(m, n) == 1 and (m - n) % 2 == 1


def squarefree_part(n: int) -> int:
    """Squarefree part of n by trial division."""
    s, d = 1, 2
    while d * d <= n:
        e = 0
        while n % d == 0:
            n //= d
            e += 1
        if e % 2:
            s *= d
        d += 1 if d == 2 else 2
    return s * n if n > 1 else s


def node_triangle(m: int, n: int) -> Tuple[int, Triangle]:
    """Rescale the node's triple to a rational triangle of area exactly s."""
    if not is_admissible(m, n):
        raise ValueError(f"{(m, n)} is not an admissible Euclid seed")
    area = m * n * (m - n) * (m + n)
    s = squarefree_part(area)
    k = isqrt(area // s)
    assert s * k * k == area
    return s, (Fraction(m * m - n * n, k), Fraction(2 * m * n, k),
               Fraction(m * m + n * n, k))


def triangle_to_point(triangle: Triangle) -> Point:
    """(a, b, c) of area N  ->  (a(a+c)/2, a^2(a+c)/2) on y^2 = x^3 - N^2 x."""
    a, _, c = triangle
    return (a * (a + c) / 2, a * a * (a + c) / 2)


def point_to_triangle(area: Fraction, point: Point) -> Triangle:
    """A point with x > 0, y != 0 back to a right triangle of area `area`."""
    x, y = point
    y = abs(y)
    if not (x > 0 and y != 0):
        raise ValueError("need x > 0 and y != 0")
    return ((x * x - area * area) / y, 2 * area * x / y, (x * x + area * area) / y)


def on_curve(area: Fraction, point: Point) -> bool:
    x, y = point
    return y * y == x ** 3 - area * area * x


def bridge(m: int, n: int) -> Dict[str, object]:
    """Full round trip: node -> triangle -> curve point -> triangle."""
    s, triangle = node_triangle(m, n)
    point = triangle_to_point(triangle)
    assert on_curve(Fraction(s), point)
    back = point_to_triangle(Fraction(s), point)
    a, b, c = back
    assert a * a + b * b == c * c and a * b == 2 * s
    return {"seed": (m, n), "s": s, "triangle": triangle, "point": point,
            "recovered": back}


if __name__ == "__main__":
    for seed in [(2, 1), (5, 4), (16, 9), (9, 8), (25, 16)]:
        data = bridge(*seed)
        a, b, c = data["triangle"]            # type: ignore[misc]
        x, y = data["point"]                  # type: ignore[misc]
        print(f"seed {str(seed):<9} s = {data['s']:<5} triangle ({a}, {b}, {c})")
        print(f"            point on y^2 = x^3 - {data['s']}^2 x:  ({x}, {y})")

