"""
Visualization: the congruent number board.

A grid over the squarefree integers up to a bound, each cell coloured by status:

  * certified congruent   - some node of the Berggren tree has this squarefree part
                            (the certifying Euclid seed is annotated);
  * refuted by descent    - the square classes the tree's own descent kills:
                            1, 2, and every prime p = 3 (mod 8);
  * open within the search - no certificate found below the seed bound.

Requires: matplotlib, numpy.  Run:  python3 viz_board.py
"""

from __future__ import annotations

from math import gcd, isqrt
from typing import Dict, List, Tuple

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.colors import ListedColormap

BOARD_MAX = 200
SEED_BOUND = 900
COLUMNS = 10


def is_admissible(m: int, n: int) -> bool:
    return m > n > 0 and gcd(m, n) == 1 and (m - n) % 2 == 1


def spf_sieve(limit: int) -> List[int]:
    spf = list(range(limit + 1))
    i = 2
    while i * i <= limit:
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    return spf


def squarefree_part(m: int, n: int, spf: List[int]) -> int:
    exponents: Dict[int, int] = {}
    for f in (m, n, m - n, m + n):
        while f > 1:
            p = spf[f]
            while f % p == 0:
                exponents[p] = exponents.get(p, 0) + 1
                f //= p
    s = 1
    for p, e in exponents.items():
        if e % 2:
            s *= p
    return s


def is_squarefree(x: int) -> bool:
    d = 2
    while d * d <= x:
        if x % (d * d) == 0:
            return False
        d += 1
    return True


def is_prime(x: int) -> bool:
    return x > 1 and all(x % d for d in range(2, isqrt(x) + 1))


def main() -> None:
    spf = spf_sieve(2 * SEED_BOUND)
    certified: Dict[int, Tuple[int, int]] = {}
    for m in range(2, SEED_BOUND + 1):
        for n in range(1, m):
            if not is_admissible(m, n):
                continue
            s = squarefree_part(m, n, spf)
            if s <= BOARD_MAX and s not in certified:
                certified[s] = (m, n)

    values = [s for s in range(1, BOARD_MAX + 1) if is_squarefree(s)]
    rows = (len(values) + COLUMNS - 1) // COLUMNS
    grid = np.full((rows, COLUMNS), np.nan)
    labels: Dict[Tuple[int, int], str] = {}

    for idx, s in enumerate(values):
        r, c = divmod(idx, COLUMNS)
        if s == 1 or s == 2 or (is_prime(s) and s % 8 == 3):
            grid[r, c] = 0.0                      # refuted by the tree's descent
            labels[(r, c)] = f"{s}\nrefuted"
        elif s in certified:
            grid[r, c] = 1.0                      # certified congruent
            m, n = certified[s]
            labels[(r, c)] = f"{s}\n({m},{n})"
        else:
            grid[r, c] = 0.5                      # open within this search
            labels[(r, c)] = f"{s}\n?"

    cmap = ListedColormap(["#d1495b", "#cfcfcf", "#00798c"])
    fig, ax = plt.subplots(figsize=(11, 0.8 * rows + 2))
    ax.imshow(grid, cmap=cmap, vmin=0, vmax=1, aspect="auto")
    for (r, c), text in labels.items():
        ax.text(c, r, text, ha="center", va="center", fontsize=7.5, color="white"
                if grid[r, c] != 0.5 else "black")
    ax.set_xticks([])
    ax.set_yticks([])
    ax.set_title(
        f"The congruent number board: squarefree $s \\leq {BOARD_MAX}$\n"
        f"teal = certified by a tree node with $m \\leq {SEED_BOUND}$   |   "
        "red = refuted by the tree's descent   |   grey = open",
        fontsize=11)
    fig.tight_layout()
    fig.savefig("congruent_number_board.png", dpi=160)
    print("wrote congruent_number_board.png")
    print(f"certified: {sum(1 for s in values if s in certified)} of {len(values)} "
          f"squarefree values up to {BOARD_MAX}")


if __name__ == "__main__":
    main()
